/**
 * Ground height for the photorealistic chase.
 *
 * Map3D's look-at altitude is meters above sea level. Writing 0 aims the lens
 * under the road, so the view ray hits the next ridge and the terrain collision
 * solver shoves that hit forward and back — the travel light rocks for the
 * whole drive. Mapbox Terrain-RGB (the same DEM the Mapbox basemap already
 * uses) gives a sea-level height without a second Google Elevation billing.
 */

export const TERRAIN_ZOOM = 10;

export function terrainRgbMeters(r: number, g: number, b: number): number {
  return -10000 + (r * 65536 + g * 256 + b) * 0.1;
}

/** XYZ tile containing this lat/lng (Mapbox / Google / OSM scheme, y down). */
export function terrainTileIndex(lat: number, lng: number, zoom = TERRAIN_ZOOM): { x: number; y: number; z: number } {
  const n = 2 ** zoom;
  const x = Math.floor(((lng + 180) / 360) * n);
  const latRad = (lat * Math.PI) / 180;
  const y = Math.floor(((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n);
  return {
    x: Math.min(n - 1, Math.max(0, x)),
    y: Math.min(n - 1, Math.max(0, y)),
    z: zoom,
  };
}

/** Pixel position inside that tile. (px, py) are continuous, 0…size. */
export function terrainPixel(
  lat: number,
  lng: number,
  zoom = TERRAIN_ZOOM,
  size = 256,
): { x: number; y: number; px: number; py: number } {
  const n = 2 ** zoom;
  const gx = ((lng + 180) / 360) * n;
  const latRad = (lat * Math.PI) / 180;
  const gy = ((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n;
  const x = Math.floor(gx);
  const y = Math.floor(gy);
  return { x, y, px: (gx - x) * size, py: (gy - y) * size };
}

export function bilinearElevation(elev: Float32Array, size: number, px: number, py: number): number {
  const x = Math.min(size - 1.001, Math.max(0, px));
  const y = Math.min(size - 1.001, Math.max(0, py));
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const tx = x - x0;
  const ty = y - y0;
  const at = (yy: number, xx: number) => elev[yy * size + xx];
  const a = at(y0, x0);
  const b = at(y0, Math.min(size - 1, x0 + 1));
  const c = at(Math.min(size - 1, y0 + 1), x0);
  const d = at(Math.min(size - 1, y0 + 1), Math.min(size - 1, x0 + 1));
  return a * (1 - tx) * (1 - ty) + b * tx * (1 - ty) + c * (1 - tx) * ty + d * tx * ty;
}

type Tile = { size: number; elev: Float32Array };

function readMapboxToken(): string {
  if (typeof window === "undefined") return "";
  const b64 = (window as Window & { __MMD_MAPBOX_B64?: string }).__MMD_MAPBOX_B64 || "";
  if (!b64) return "";
  try {
    return atob(b64);
  } catch {
    return "";
  }
}

/**
 * Cached Terrain-RGB sampler. `sample` is synchronous and returns null until
 * the tile has decoded, so the chase never waits on the network.
 */
export class TerrainAltitude {
  private tiles = new Map<string, Tile | "pending" | "fail">();
  private order: string[] = [];
  private token = "";

  constructor(private tokenSource: () => string = readMapboxToken) {}

  prefetch(lat: number, lng: number): void {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
    if (typeof fetch !== "function" || typeof document === "undefined") return;
    const token = this.token || (this.token = this.tokenSource());
    if (!token) return;
    const { x, y, z } = terrainTileIndex(lat, lng, TERRAIN_ZOOM);
    const key = `${z}/${x}/${y}`;
    if (this.tiles.has(key)) return;
    this.tiles.set(key, "pending");
    this.order.push(key);
    while (this.order.length > 24) {
      const old = this.order.shift();
      if (old && old !== key) this.tiles.delete(old);
    }
    void this.load(key, token, x, y, z);
  }

  /** Meters above sea level, or null while the tile is still loading. */
  sample(lat: number, lng: number): number | null {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    const { x, y, z } = terrainTileIndex(lat, lng, TERRAIN_ZOOM);
    const tile = this.tiles.get(`${z}/${x}/${y}`);
    if (!tile || tile === "pending" || tile === "fail") return null;
    const px = terrainPixel(lat, lng, TERRAIN_ZOOM, tile.size);
    const meters = bilinearElevation(tile.elev, tile.size, px.px, px.py);
    if (!Number.isFinite(meters) || meters < -500 || meters > 9000) return null;
    return meters;
  }

  private async load(key: string, token: string, x: number, y: number, z: number): Promise<void> {
    try {
      const url = `https://api.mapbox.com/v4/mapbox.terrain-rgb/${z}/${x}/${y}.pngraw?access_token=${encodeURIComponent(token)}`;
      const res = await fetch(url);
      if (!res.ok) throw new Error(String(res.status));
      const blob = await res.blob();
      const bmp = await createImageBitmap(blob);
      const canvas = document.createElement("canvas");
      canvas.width = bmp.width;
      canvas.height = bmp.height;
      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (!ctx) throw new Error("no2d");
      ctx.drawImage(bmp, 0, 0);
      const img = ctx.getImageData(0, 0, bmp.width, bmp.height);
      const size = bmp.width;
      const elev = new Float32Array(size * bmp.height);
      for (let i = 0; i < elev.length; i++) {
        const o = i * 4;
        elev[i] = terrainRgbMeters(img.data[o], img.data[o + 1], img.data[o + 2]);
      }
      bmp.close?.();
      if (size < 2) throw new Error("short tile");
      this.tiles.set(key, { size, elev });
    } catch (err) {
      this.tiles.set(key, "fail");
      console.warn("[mmd] terrain altitude unavailable", err);
    }
  }
}

export function createTerrainAltitude(): TerrainAltitude {
  return new TerrainAltitude();
}
