/** Dynamically load the Google Maps JavaScript API (once). */

declare global {
  interface Window {
    google?: typeof google;
    __MMD_GOOGLE_MAPS_READY__?: Promise<typeof google>;
    __mmdGoogleMapsCb?: () => void;
  }
}

function mapCtorReady(g: typeof google | undefined): boolean {
  const MapCtor = g?.maps && (g.maps as { Map?: unknown }).Map;
  return typeof MapCtor === "function";
}

function mockRequested(): boolean {
  try {
    return new URLSearchParams(window.location.search).get("mmd3d") === "mock";
  } catch {
    return false;
  }
}

/**
 * Headless / CI stub for `?mmd3d=mock`.
 *
 * The Photorealistic Maps JS key is referrer-restricted to the Pages host, so
 * GitHub Actions (and other localhost previews) hang or auth-fail on the real
 * script. The maps3d mock never needs `google.maps.Map` — only a Map ctor so
 * GoogleMapShim can construct and boot the 3D scene double.
 */
function installMockGoogleMaps(): typeof google {
  if (mapCtorReady(window.google)) return window.google!;

  class MockMap {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    constructor(_el?: unknown, _opts?: unknown) {}
    setOptions() {}
    setCenter() {}
    setZoom() {}
    setTilt() {}
    setHeading() {}
    getDiv() {
      return document.createElement("div");
    }
  }

  class MockPolyline {
    setMap() {}
    setOptions() {}
    setPath() {}
  }

  class MockOverlayView {
    setMap() {}
    getProjection() {
      return null;
    }
    draw() {}
    onAdd() {}
    onRemove() {}
  }

  const maps = {
    Map: MockMap,
    Polyline: MockPolyline,
    OverlayView: MockOverlayView,
    LatLng: class {
      constructor(
        public lat: number,
        public lng: number,
      ) {}
    },
    LatLngBounds: class {
      extend() {
        return this;
      }
      getCenter() {
        return { lat: () => 0, lng: () => 0 };
      }
    },
    event: {
      addListener() {
        return { remove() {} };
      },
      addListenerOnce(_t: unknown, _e: string, fn: () => void) {
        queueMicrotask(fn);
        return { remove() {} };
      },
      clearInstanceListeners() {},
    },
    RenderingType: { VECTOR: "VECTOR", RASTER: "RASTER" },
  };

  (window as Window & { google: typeof google }).google = { maps } as unknown as typeof google;
  return window.google!;
}

const GOOGLE_LOAD_TIMEOUT_MS = 20_000;

export async function loadGoogleMaps(apiKey: string): Promise<typeof google> {
  if (typeof window === "undefined") {
    throw new Error("Google Maps requires a browser");
  }
  // Contract tests / CI: never touch maps.googleapis.com.
  if (mockRequested()) {
    return installMockGoogleMaps();
  }
  if (mapCtorReady(window.google)) {
    return window.google!;
  }
  if (window.__MMD_GOOGLE_MAPS_READY__) {
    return window.__MMD_GOOGLE_MAPS_READY__;
  }

  window.__MMD_GOOGLE_MAPS_READY__ = new Promise((resolve, reject) => {
    let settled = false;
    const fail = (err: Error) => {
      if (settled) return;
      settled = true;
      window.__MMD_GOOGLE_MAPS_READY__ = undefined;
      clearTimeout(timer);
      reject(err);
    };

    const prevAuth = (window as Window & { gm_authFailure?: () => void }).gm_authFailure;
    (window as Window & { gm_authFailure?: () => void }).gm_authFailure = () => {
      try {
        prevAuth?.();
      } catch {
        /* ignore */
      }
      fail(new Error("Google Maps API key invalid or restricted"));
    };

    const finish = () => {
      if (!mapCtorReady(window.google)) {
        fail(new Error("Google Maps Map constructor unavailable after load"));
        return;
      }
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(window.google!);
    };

    const timer = window.setTimeout(() => {
      fail(new Error(`Google Maps load timed out after ${GOOGLE_LOAD_TIMEOUT_MS}ms`));
    }, GOOGLE_LOAD_TIMEOUT_MS);

    // Classic callback bootstrap — populates google.maps.Map reliably.
    const existing = document.querySelector<HTMLScriptElement>(
      'script[data-mmd-google-maps="1"]',
    );
    if (existing) {
      if (mapCtorReady(window.google)) {
        finish();
        return;
      }
      existing.addEventListener("load", () => finish());
      existing.addEventListener("error", () => fail(new Error("Google Maps script error")));
      return;
    }

    if (!apiKey) {
      fail(new Error("Google Maps API key missing"));
      return;
    }

    window.__mmdGoogleMapsCb = () => {
      try {
        finish();
      } finally {
        delete window.__mmdGoogleMapsCb;
      }
    };

    const script = document.createElement("script");
    script.dataset.mmdGoogleMaps = "1";
    script.async = true;
    script.defer = true;
    script.src =
      `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(apiKey)}` +
      `&v=weekly&libraries=maps3d&callback=__mmdGoogleMapsCb`;
    script.onerror = () => fail(new Error("Google Maps script error"));
    document.head.appendChild(script);
  });

  return window.__MMD_GOOGLE_MAPS_READY__;
}
