/**
 * Lazy per-trip geometry.
 *
 * `data/index.json` ships every trip with an atlas-grade `route_overview`
 * polyline and a `geometry` descriptor. The full `route_path` + playback
 * timeline for a trip live in `data/trips/<id>.json` (content-hash query for
 * cache busting) and are fetched the first time the user focuses or plays
 * that trip. Travel segments in the chunk reference index ranges into
 * `route_path` (`i0`/`i1` + interpolated endpoints `p0`/`p1`) so the
 * coordinates ship once; `hydrateTripChunk` expands them back into the
 * `segment.path` arrays the playback engine consumes.
 */

import type { Trip } from "../types";
import { rewriteMediaUrls } from "../media-cdn";

export type LatLng = [number, number];

export interface TripGeometryRef {
  url: string;
  v: string;
  bytes: number;
  points: number;
  segments: number;
}

export interface RangedSegment {
  type: string;
  i0?: number;
  i1?: number;
  p0?: LatLng;
  p1?: LatLng;
  path?: LatLng[];
  [key: string]: unknown;
}

export interface TripChunk {
  version: number;
  id: string;
  route_path: LatLng[];
  playback: {
    segments: RangedSegment[];
    total_video_ms: number;
    [key: string]: unknown;
  };
}

export interface HydratedGeometry {
  route_path: LatLng[];
  playback: TripChunk["playback"];
}

export interface TripGeometryEvent {
  trip: Trip;
  ms: number;
  bytes: number;
}

interface LoaderConfig {
  /** Base URL for `data/` (default `./data/`). */
  dataBase: string;
  /** Media CDN base for thumb rewriting inside playback segments ("" = none). */
  mediaCdnBase: string;
  /** Called after a trip's geometry has been attached. */
  onLoaded?: (ev: TripGeometryEvent) => void;
}

const config: LoaderConfig = { dataBase: "./data/", mediaCdnBase: "" };
const inflight = new Map<string, Promise<Trip>>();
const loadedIds = new Set<string>();

export function configureTripGeometry(next: Partial<LoaderConfig>): void {
  Object.assign(config, next);
}

/** Expand ranged travel segments into concrete `[lat, lng]` paths. */
export function hydrateTripChunk(chunk: TripChunk): HydratedGeometry {
  const route = chunk.route_path || [];
  const playback = { ...chunk.playback, segments: [] as RangedSegment[] };
  for (const seg of chunk.playback?.segments || []) {
    if (seg.type !== "travel") {
      playback.segments.push(seg);
      continue;
    }
    if (Array.isArray(seg.path)) {
      playback.segments.push(seg);
      continue;
    }
    if (typeof seg.i0 !== "number" || typeof seg.i1 !== "number" || !seg.p0 || !seg.p1) {
      playback.segments.push({ ...seg, path: [] });
      continue;
    }
    const { i0, i1, p0, p1, ...rest } = seg;
    const path: LatLng[] = [p0];
    for (let i = i0; i <= i1 && i < route.length; i++) path.push(route[i]);
    path.push(p1);
    playback.segments.push({ ...rest, path });
  }
  return { route_path: route, playback };
}

export function tripGeometryReady(trip: Trip | null | undefined): boolean {
  if (!trip) return false;
  if (trip.geometry_loaded === true) return true;
  // Legacy monolithic data (no descriptor) already carries the full playback.
  const pb = trip.playback as { segments?: unknown[] } | undefined;
  return !trip.geometry && Array.isArray(pb?.segments);
}

function chunkUrl(trip: Trip): string {
  const ref = trip.geometry as TripGeometryRef | undefined;
  if (!ref?.url) throw new Error(`Trip ${trip.id} has no geometry descriptor`);
  return `${config.dataBase}${ref.url}`;
}

async function fetchChunk(trip: Trip, priority: "high" | "low"): Promise<TripChunk> {
  const url = chunkUrl(trip);
  const init: RequestInit & { priority?: string } = { priority };
  const res = await fetch(url, init);
  if (!res.ok) throw new Error(`Trip geometry ${res.status} for ${trip.id}`);
  return (await res.json()) as TripChunk;
}

function attach(trip: Trip, chunk: TripChunk): void {
  const hydrated = hydrateTripChunk(chunk);
  const playback = config.mediaCdnBase
    ? (rewriteMediaUrls(hydrated.playback, config.mediaCdnBase) as HydratedGeometry["playback"])
    : hydrated.playback;
  trip.route_path = hydrated.route_path;
  trip.playback = playback;
  trip.geometry_loaded = true;
  loadedIds.add(trip.id);
}

/**
 * Resolve once the trip carries full `route_path` + `playback`. Idempotent;
 * concurrent callers share one request.
 */
export function ensureTripGeometry(trip: Trip, opts: { priority?: "high" | "low" } = {}): Promise<Trip> {
  if (tripGeometryReady(trip)) return Promise.resolve(trip);
  const existing = inflight.get(trip.id);
  if (existing) return existing;
  const t0 = performance.now();
  const p = fetchChunk(trip, opts.priority ?? "high")
    .then((chunk) => {
      attach(trip, chunk);
      const ref = trip.geometry as TripGeometryRef | undefined;
      config.onLoaded?.({ trip, ms: performance.now() - t0, bytes: ref?.bytes ?? 0 });
      return trip;
    })
    .finally(() => {
      inflight.delete(trip.id);
    });
  inflight.set(trip.id, p);
  return p;
}

/** Fire-and-forget warm-up (hover / focus / idle). Errors are swallowed. */
export function prefetchTripGeometry(trip: Trip | null | undefined): void {
  if (!trip || tripGeometryReady(trip) || inflight.has(trip.id)) return;
  ensureTripGeometry(trip, { priority: "low" }).catch(() => {});
}

export function loadedTripIds(): string[] {
  return [...loadedIds];
}

export function inflightTripIds(): string[] {
  return [...inflight.keys()];
}
